/*
  # Prova Paraná Recomposição — 2ª Avaliação 2026 (parte 3 de 3)

  Carga em prova_resultados com ano_prova = '2026' e semestre = '2' (a 2ª avaliação do ano
  ocupa o "2º semestre" do app). Fonte: export SAEP "PARANÁ RECOMPOSIÇÃO - 2ª AVALIAÇÃO 2026",
  uma planilha por ESCOLA-COMPONENTE-SERIE (ex.: ANITA-LP-3ANO.xlsx) + HABILIDADE-*.xlsx.

  Mesmo formato do upload do app (UploadForm.processExcelData):
    - uma linha por aluno x habilidade; habilidade_id = 'H 01'..'H nn' (cabeçalho da planilha);
    - 'acertos / total' -> acertos, total, percentual; '-' (ausente) -> 0/0 com avaliado = false;
    - turma = 'Código da Turma', nivel_aprendizagem = 'Nível de Aprendizagem' ('-' p/ ausentes);
    - unidade com a grafia do banco (UNIDADES_OPCOES).
  Além do upload: habilidade_codigo, descricao_habilidade e componente_habilidade_id já vêm
  preenchidos pelas planilhas HABILIDADE-* desta edição, casando pela POSIÇÃO (Dxxx).
  Atenção: nesta edição a numeração H mudou em relação à tabela componentes_habilidades
  (ex.: MT 6º ano H 05 = D009_M, antes H 05 = D005_M) — por isso o casamento NÃO usa o Hnn.

  Reexecutável: antes de inserir, apaga as linhas 2026/2 das mesmas (unidade, série,
  componente) desta parte. Cada parte roda numa transação; as partes são independentes.

  Esta parte: 4 escolas, 22 planilhas, 1948 alunos, 34937 linhas.
    SANTO-AGOSTINHO-LP-3ANO.xlsx     SANTO AGOSTINHO C E EF M                 3º ano LP    77 alunos x 15 H =  1155
    SANTO-AGOSTINHO-LP-6ANO.xlsx     SANTO AGOSTINHO C E EF M                 6º ano LP    64 alunos x 15 H =   960
    SANTO-AGOSTINHO-LP-9ANO.xlsx     SANTO AGOSTINHO C E EF M                 9º ano LP    96 alunos x 15 H =  1440
    SANTO-AGOSTINHO-MAT-3ANO.xlsx    SANTO AGOSTINHO C E EF M                 3º ano MT    77 alunos x 22 H =  1694
    SANTO-AGOSTINHO-MAT-6ANO.xlsx    SANTO AGOSTINHO C E EF M                 6º ano MT    64 alunos x 20 H =  1280
    SANTO-AGOSTINHO-MAT-9ANO.xlsx    SANTO AGOSTINHO C E EF M                 9º ano MT    96 alunos x 21 H =  2016
    TARSILA-LP-3ANO.xlsx             TARSILA DO AMARAL C E EF M               3º ano LP   105 alunos x 15 H =  1575
    TARSILA-LP-6ANO.xlsx             TARSILA DO AMARAL C E EF M               6º ano LP   134 alunos x 15 H =  2010
    TARSILA-LP-9ANO.xlsx             TARSILA DO AMARAL C E EF M               9º ano LP   138 alunos x 15 H =  2070
    TARSILA-MAT-3ANO.xlsx            TARSILA DO AMARAL C E EF M               3º ano MT   105 alunos x 22 H =  2310
    TARSILA-MAT-6ANO.xlsx            TARSILA DO AMARAL C E EF M               6º ano MT   134 alunos x 20 H =  2680
    TARSILA-MAT-9ANO.xlsx            TARSILA DO AMARAL C E EF M               9º ano MT   138 alunos x 21 H =  2898
    TEREZA-LP-3ANO.xlsx              TEREZA DA S RAMOS C E PROFA EF M         3º ano LP    26 alunos x 15 H =   390
    TEREZA-LP-6ANO.xlsx              TEREZA DA S RAMOS C E PROFA EF M         6º ano LP    94 alunos x 15 H =  1410
    TEREZA-LP-9ANO.xlsx              TEREZA DA S RAMOS C E PROFA EF M         9º ano LP   133 alunos x 15 H =  1995
    TEREZA-MAT-3ANO.xlsx             TEREZA DA S RAMOS C E PROFA EF M         3º ano MT    26 alunos x 22 H =   572
    TEREZA-MAT-6ANO.xlsx             TEREZA DA S RAMOS C E PROFA EF M         6º ano MT    94 alunos x 20 H =  1880
    TEREZA-MAT-9ANO.xlsx             TEREZA DA S RAMOS C E PROFA EF M         9º ano MT   133 alunos x 21 H =  2793
    VICTOR-LP-6ANO.xlsx              VICTOR DO AMARAL C E PROF EFM ETI PROFI  6º ano LP    43 alunos x 15 H =   645
    VICTOR-LP-9ANO.xlsx              VICTOR DO AMARAL C E PROF EFM ETI PROFI  9º ano LP    64 alunos x 15 H =   960
    VICTOR-MAT-6ANO.xlsx             VICTOR DO AMARAL C E PROF EFM ETI PROFI  6º ano MT    43 alunos x 20 H =   860
    VICTOR-MAT-9ANO.xlsx             VICTOR DO AMARAL C E PROF EFM ETI PROFI  9º ano MT    64 alunos x 21 H =  1344
*/

BEGIN;

-- Descritor desta edição que ainda não existe em componentes_habilidades (prova-parana).
ON CONFLICT (tipo_prova, ano_escolar, componente, posicao) DO NOTHING;

-- Planilhas desta parte (k = chave usada em _carga_aluno).
CREATE TEMP TABLE _carga_arquivo (k int PRIMARY KEY, unidade text, ano_escolar text, componente text) ON COMMIT DROP;

-- Descritores da edição: H n de cada (série, componente) -> posição/descrição (HABILIDADE-*.xlsx).
CREATE TEMP TABLE _carga_habilidade (ano_escolar text, componente text, n int, posicao text, descricao text,
  PRIMARY KEY (ano_escolar, componente, n)) ON COMMIT DROP;

-- Alunos: hs = resultados de H 01..H nn separados por espaço ('acertos/total' ou '-').
CREATE TEMP TABLE _carga_aluno (k int, turma text, nome_aluno text, nivel text, hs text) ON COMMIT DROP;

-- Reexecução segura: remove a carga 2026/2 anterior das mesmas planilhas.
DELETE FROM prova_resultados pr
USING _carga_arquivo a
WHERE pr.ano_prova = '2026' AND pr.semestre = '2'
  AND pr.unidade = a.unidade AND pr.ano_escolar = a.ano_escolar AND pr.componente = a.componente;

   avaliado, habilidade_id, habilidade_codigo, descricao_habilidade, acertos, total, percentual,
   componente_habilidade_id)
SELECT '2026', '2', a.unidade, a.ano_escolar, a.componente, al.turma, al.nome_aluno, al.nivel,
       r.total > 0, 'H ' || lpad(h.n::text, 2, '0'), hb.posicao, hb.descricao, r.acertos, r.total,
       CASE WHEN r.total > 0 THEN LEAST(100, GREATEST(0, r.acertos::float8 / r.total * 100)) ELSE 0 END,
       ch.id
FROM _carga_aluno al
JOIN _carga_arquivo a ON a.k = al.k
CROSS JOIN LATERAL unnest(string_to_array(al.hs, ' ')) WITH ORDINALITY AS h(v, n)
JOIN _carga_habilidade hb
  ON hb.ano_escolar = a.ano_escolar AND hb.componente = a.componente AND hb.n = h.n
CROSS JOIN LATERAL (
  SELECT CASE WHEN h.v = '-' THEN 0 ELSE split_part(h.v, '/', 1)::int END AS acertos,
         CASE WHEN h.v = '-' THEN 0 ELSE split_part(h.v, '/', 2)::int END AS total
) r
LEFT JOIN componentes_habilidades ch
  ON ch.tipo_prova = 'prova-parana' AND ch.ano_escolar = a.ano_escolar
  AND ch.componente = a.componente AND ch.posicao = hb.posicao;

COMMIT;

